fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If the coefficient grid is exactly 1x1, return its sole entry.
    // Otherwise, return 0.0.
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Validate inputs
    assert!(
        x.len() == y.len() && !x.is_empty(),
        "Input arrays must have the same positive length"
    );
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    for row in &c {
        assert!(!row.is_empty(), "Rows in coefficient grid must be non-empty");
    }

    // Determine the fill value (either the single coefficient or zero)
    let fill = default_value(&c);

    // Construct the output vector of the required length
    vec![fill; x.len()]
}

